	   , BULD_NM
	   , ARCD
	   , LEGCD
	   , BUN
	   , JI
       , PLOT_GB_CD
       , SP_PLOT_NM
       , BLOCK_NM
       , CREAT_DE
       , BATCH_YN
       , CREAT_USER_NO
       , UPDT_USER_NO
) VALUES (
	   #{buldRegstrPk}
	   , #{regstrGbCd}
	   , #{plotLoc}
	   , #{buldNm}
	   , #{arcd}
	   , #{legcd}
	   , #{bun}
	   , #{ji}
       , #{plotGbCd}
       , #{spPlotNm}
       , #{blockNm}
       , #{creatDe}
       , #{batchYn}
       , #{mngrno}
       , #{mngrno}
)

